"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[6041],{9701(n,e,a){a.r(e),a.d(e,{default:()=>d});a(6540);var r=a(1656),t=a(6025);const i="labPage_Jrqu",s="labHeader_K7aL",o="labFrame_qNMX";var l=a(4848);function d(){return(0,l.jsx)(r.A,{title:"Animated RNN companion lab",description:"An interactive 3D walkthrough of tokens, embeddings, recurrent memory, prediction, and backpropagation through time.",children:(0,l.jsxs)("main",{className:i,children:[(0,l.jsxs)("header",{className:s,children:[(0,l.jsxs)("div",{children:[(0,l.jsx)("span",{children:"Part V \xb7 Interactive companion"}),(0,l.jsx)("h1",{children:"Animated RNN walkthrough"}),(0,l.jsx)("p",{children:"Explore the complete path from words and token IDs to embeddings, recurrent memory, next-token prediction, and learning."})]}),(0,l.jsx)("a",{href:(0,t.Ay)("/part5-deep-learning-and-llms/10-recurrent-neural-networks"),children:"Read the RNN chapter"})]}),(0,l.jsx)("iframe",{className:o,srcDoc:'<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8" />\n  <meta name="viewport" content="width=device-width,initial-scale=1" />\n  <title>Animated RNN Companion Lab: Words, Memory, Prediction, and Training</title>\n  <link rel="stylesheet" href="/tutorials/css/book.css?v=20260730-currency-final">\n  <link rel="stylesheet" href="/tutorials/css/rnn-animated-tutorial.css">\n  <script defer src="/tutorials/vendor/babylon/7.54.2/babylon.js"><\/script>\n  <script defer src="/tutorials/js/rnn-animated-tutorial.js"><\/script>\n</head>\n<body class="rnn-lesson-body">\n  <main class="rnn-lesson-shell">\n    <section class="rnn-stage" aria-label="Animated RNN lesson">\n      <canvas id="rnn-canvas" aria-label="3D animated recurrent neural network tutorial"></canvas>\n\n      <aside class="rnn-narration" aria-live="polite">\n        <div class="rnn-kicker">Interactive animation \xb7 Babylon.js</div>\n        <h1>Understanding the Recurrent Neural Network</h1>\n        <p class="rnn-subtitle">From words to memory to next-word prediction</p>\n\n        <div class="rnn-voice-card">\n          <div class="rnn-avatar" aria-hidden="true">M</div>\n          <div>\n            <strong>Maya, human-style narrator</strong>\n            <p>\n              Warm, patient, native-English classroom delivery. Recorded MP3 narration is used when generated files are available.\n            </p>\n            <p id="audio-status" class="rnn-audio-status">Recorded narration files are not loaded yet.</p>\n          </div>\n        </div>\n\n        <div class="rnn-progress">\n          <span id="scene-count">Scene 1 / 28</span>\n          <span id="scene-time">0:00</span>\n        </div>\n        <div class="rnn-progress-bar" aria-hidden="true"><span id="scene-progress"></span></div>\n\n        <h2 id="scene-title">Opening: what are we trying to do?</h2>\n        <p id="scene-caption">\n          We show a sequence one word at a time and ask the network to predict what comes next.\n        </p>\n        <p id="scene-narration" class="rnn-script">\n          Let\u2019s build one of the simplest language models ever created: the Recurrent Neural Network, or RNN.\n        </p>\n\n        <div id="scene-equation" class="rnn-equation" hidden></div>\n\n        <div class="rnn-controls">\n          <button id="prev-scene" type="button" aria-label="Previous scene">Previous</button>\n          <button id="play-pause" type="button" aria-label="Play or pause animation">Play</button>\n          <button id="next-scene" type="button" aria-label="Next scene">Next</button>\n          <button id="voice-toggle" type="button" aria-label="Toggle recorded narration">Narration Off</button>\n        </div>\n\n        <label class="rnn-slider-label" for="scene-slider">\n          Scene timeline\n          <input id="scene-slider" type="range" min="0" max="27" value="0">\n        </label>\n\n        <div class="rnn-legend" aria-label="Animation color legend">\n          <span><i class="blue"></i> input / embeddings</span>\n          <span><i class="green"></i> hidden memory</span>\n          <span><i class="purple"></i> output prediction</span>\n          <span><i class="red"></i> loss / learning</span>\n        </div>\n      </aside>\n    </section>\n\n    <section class="rnn-notes wrap">\n      <p>\n        This interactive chapter is a companion to\n        <a href="/tutorials/part5-deep-learning-and-llms/10-recurrent-neural-networks">Chapter 10 \u2014 Recurrent Neural Networks</a>.\n        It uses a live 3D scene to make the RNN data flow physical: words become token IDs, IDs become embeddings,\n        embeddings enter a recurrent cell, hidden state carries memory, logits become probabilities, and loss flows backward\n        through time during training.\n      </p>\n      <p>\n        Use the scene slider for manual review. Generate MP3 narration with\n        <code>scripts/generate-rnn-narration-elevenlabs.mjs</code>, then turn narration on to sync the animation to recorded audio.\n        Captions remain available when audio files are not present.\n      </p>\n    </section>\n  </main>\n</body>\n</html>\n',title:"Interactive animated recurrent neural network tutorial",allow:"autoplay"})]})})}}}]);